<template>
  <div class="hist-detalle">
    <section class="hist-resumen">
      <div class="hist-top"><span class="hist-codigo">{{ registro.codigo }}</span><span class="hist-estado">{{ estado }}</span></div>
      <h2>{{ registro.titulo }}</h2>
      <div class="hist-personas"><span><small>Solicitante</small><strong>{{ registro.solicitante_nombre || 'Sin registro' }}</strong></span><span><small>Área solicitante</small><strong>{{ registro.area_nombre || 'Sin registro' }}</strong></span><span><small>Fecha de solicitud</small><strong>{{ fecha(registro.creado_en) }}</strong></span></div>
    </section>
    <section class="hist-seccion"><h3>Datos del requerimiento</h3><dl class="hist-datos"><div><dt>Tipo</dt><dd>{{ registro.tipo_nombre || registro.tipo || 'Sin registro' }}</dd></div><div><dt>Cantidad solicitada</dt><dd>{{ registro.cantidad }} unidades</dd></div><div><dt>Monto estimado</dt><dd>{{ dinero(registro.monto_estimado) }}</dd></div><div class="hist-ancho"><dt>Descripción</dt><dd>{{ registro.descripcion || 'Sin descripción' }}</dd></div><div class="hist-ancho" v-if="registro.especificaciones"><dt>Especificaciones</dt><dd>{{ registro.especificaciones }}</dd></div><div class="hist-ancho" v-if="registro.justificacion"><dt>Justificación</dt><dd>{{ registro.justificacion }}</dd></div></dl></section>
    <section class="hist-seccion"><h3>Registros de compra y almacén</h3><div class="hist-movimientos"><article v-for="m in movimientos" :key="m.titulo"><div class="hist-mov-head"><IconoSigta :nombre="m.icono" :tamano="19" /><h4>{{ m.titulo }}</h4><span>{{ m.registrado ? 'Registrado' : 'Pendiente' }}</span></div><strong class="hist-valor">{{ m.valor }}</strong><p>{{ m.persona }}</p><small v-if="m.fecha">{{ fecha(m.fecha) }}</small><p v-if="m.observacion" class="hist-observacion">{{ m.observacion }}</p></article></div></section>
    <section class="hist-seccion"><h3>Documentos del expediente</h3><div class="hist-documentos"><button v-for="doc in documentos" :key="doc.nombre" @click="$emit('ver', doc.url, doc.nombre)"><IconoSigta nombre="solicitudes" :tamano="20" /><span><strong>{{ doc.nombre }}</strong><small>Ver documento adjunto</small></span><span aria-hidden="true">↗</span></button></div><p v-if="!documentos.length" class="hist-vacio">No hay documentos adjuntos en este expediente.</p></section>
    <section v-if="confirmadas.length" class="hist-seccion"><h3>Actas de conformidad y firmas</h3><article v-for="a in confirmadas" :key="a.id" class="hist-acta"><div class="hist-top"><strong>Entrega respaldada con acta</strong><span class="hist-estado">Firmada</span></div><dl class="hist-datos"><div><dt>Recibe</dt><dd>{{ a.datos.recibe }}</dd></div><div><dt>Entrega</dt><dd>{{ a.datos.entrega }}</dd></div><div><dt>Fecha de registro</dt><dd>{{ fecha(a.confirmado_en) }}</dd></div><div><dt>Cantidad entregada</dt><dd>{{ a.datos.cantidad_entregada }} unidades</dd></div><div class="hist-ancho" v-if="a.datos.observaciones"><dt>Observaciones</dt><dd>{{ a.datos.observaciones }}</dd></div></dl><div class="hist-acta-acciones"><button class="sia-secondary" @click="$emit('ver', a.original_url, 'Acta original')">Ver acta original</button><button class="sia-primary" @click="$emit('ver', a.firmado_url, 'Acta firmada')">Ver PDF firmado</button></div><small class="hist-referencia">Referencia: {{ a.referencia }}</small></article></section>
    <p v-if="error" class="hist-error" role="alert">{{ error }}</p>
  </div>
</template>
<script setup>
import { computed } from 'vue'
import IconoSigta from './IconoSigta.vue'
const props = defineProps({ registro: { type: Object, required: true }, estado: String, actas: { type: Array, default: () => [] }, error: String })
defineEmits(['ver'])
const confirmadas = computed(() => props.actas.filter(a => a.confirmado_en))
const dinero = v => v == null || v === '' ? 'Sin registro' : `Bs. ${Number(v).toLocaleString('es-BO', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
const fecha = v => v ? new Date(v).toLocaleString('es-BO', { dateStyle: 'medium', timeStyle: 'short' }) : 'Sin registro'
const documentos = computed(() => [['proforma', 'Proforma'], ['poa', 'POA'], ['certificacion_presupuestaria', 'Certificación presupuestaria'], ['comprobante_compra', 'Factura o recibo'], ['acta_conformidad', 'Acta de conformidad']].filter(([campo]) => props.registro[campo]).map(([campo, nombre]) => ({ nombre, url: props.registro[campo] })))
const movimientos = computed(() => {
  const r = props.registro
  return [
    { titulo: 'Desembolso', icono: 'compras', registrado: r.monto_desembolsado != null && r.monto_desembolsado !== '', valor: dinero(r.monto_desembolsado), persona: `Recibe: ${r.responsable_adquisicion || 'Sin registro'}`, fecha: r.fondos_recibidos_en },
    { titulo: 'Compra realizada', icono: 'compras', registrado: !!r.fecha_compra, valor: dinero(r.monto_real), persona: `Proveedor: ${r.proveedor || 'Sin registro'}`, fecha: r.fecha_compra, observacion: r.observacion_verificacion },
    { titulo: 'Entrada de almacén', icono: 'almacen', registrado: !!r.fecha_ingreso_almacen, valor: r.cantidad_recibida ? `${r.cantidad_recibida} unidades recibidas` : 'Sin entrada registrada', persona: `Recibido por: ${r.responsable_recepcion || 'Sin registro'}`, fecha: r.fecha_ingreso_almacen, observacion: r.observacion_ingreso },
    { titulo: 'Salida de almacén', icono: 'salir', registrado: !!r.fecha_despacho_almacen, valor: r.cantidad_entregada ? `${r.cantidad_entregada} unidades despachadas` : 'Sin salida registrada', persona: `Entregado a: ${r.entregado_a || 'Sin registro'}`, fecha: r.fecha_despacho_almacen, observacion: r.observacion_salida },
  ]
})
</script>
<style scoped>
