play:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.hist-documentos button{display:flex;align-items:center;gap:12px;text-align:left;padding:15px;border:1px solid #d8e5f4;border-radius:9px;background:#f8fafd;color:var(--sigta-azul);cursor:pointer;font:inherit}.hist-documentos button:hover{background:#edf4fc;border-color:var(--sigta-azul)}.hist-documentos button>span:nth-child(2){flex:1}.hist-documentos strong,.hist-documentos small{display:block}.hist-documentos strong{font-size:13px}.hist-documentos small{font-size:11px;margin-top:5px;color:#607795}.hist-acta{padding:18px;background:#f8fafd;border:1px solid #d8e5f4;border-radius:10px;margin-top:12px}.hist-acta .hist-datos{margin:18px 0;grid-template-columns:repeat(2,minmax(0,1fr))}.hist-acta-acciones{display:flex;gap:10px;flex-wrap:wrap}.hist-referencia{display:block;margin-top:14px;color:#607795;overflow-wrap:anywhere}.hist-vacio{font-size:13px;color:#607795}.hist-error{padding:14px;border-radius:8px;background:var(--sigta-error-fondo);color:var(--sigta-error)}@media(max-width:650px){.hist-resumen,.hist-seccion{padding:16px}.hist-personas,.hist-datos,.hist-movimientos,.hist-documentos{grid-template-columns:1fr}.hist-resumen h2{font-size:20px}.hist-mov-head{flex-wrap:wrap}}
</style>
